func rotateChars(s, n) =
  {
    local alpha = "abcdefghijklmnopqrstuvwxyz"
    local res = ""
    for (i: 1 .. s.textLen() step 1) {
      local ch = s.segment(i, 1)
      local lower = ch.lowercase()
      local idx = -1
      for (j: 1 .. 26 step 1) {
        if (alpha.segment(j, 1) === lower) {
          idx = j
        }
      }
      if (idx == -1) {
        res = res _ ch
      } else {
        local newCh = alpha.segment(idx + n - 1 % 26 + 1, 1)
        res = res _ (if (ch === lower) {
          newCh
        } else {
          newCh.uppercase()
        })
      }
    }
    res
  }
