func knapsack(wt, val, cap) =
  {
    local n = wt.listLen()
    local dp = []
    for (i: 1 .. cap + 1 step 1) {
      dp.add(0)
    }
    for (i: 1 .. n step 1) {
      for (w: cap + 1 .. 1 step -1) {
        if (wt[i] <= w - 1) {
          local test = dp[w - wt[i]] + val[i]
          if (test > dp[w]) {
            dp[w] = test
          }
        }
      }
    }
    dp[cap + 1]
  }
