func solve(row, n, cols, diag1, diag2) =
  {
    if (row > n) {
      1
    } else {
      local count = 0
      for (c: 1 .. n step 1) {
        if ((!cols.containsItem(c)) && (!diag1.containsItem(row - c)) && (!diag2.containsItem(row + c))) {
          cols.add(c)
          diag1.add(row - c)
          diag2.add(row + c)
          count = count + solve(row + 1, n, cols, diag1, diag2)
          cols.remove(cols.listLen())
          diag1.remove(diag1.listLen())
          diag2.remove(diag2.listLen())
        }
      }
      count
    }
  }

func nQueens(n) =
