      while (true) {
        local p1 = i * (3 * i - 1) / 2
        local p2 = i * (3 * i + 1) / 2
        if (p1 <= n) {
          pent.add([p1, i])
        }
        if (p2 <= n) {
          pent.add([p2, i])
        }
        if (p1 > n && p2 > n) {
          i = n + 1
        }
        i = i + 1
      }
