      for (j: 1 .. pent.listLen() step 1) {
        local pv = pent[j][1]
        local sign = if (mod(pent[j][2], 2) == 1) {
          1
        } else {
          -1
        }
        if (k - 1 >= pv) {
          pk = pk + sign * p[k - pv]
        }
      }
      p[k] = pk
    }
    p[n + 1]
  }

