func partitionDP(n) =
  {
    local p = []
    for (i: 0 .. n step 1) {
      p.add(0)
    }
    p[1] = 1
    for (k: 2 .. n + 1 step 1) {
      local sum = 0
      local i = 1
      local cont = true
      while (cont) {
        local g1 = i * (3 * i - 1) / 2
        local g2 = i * (3 * i + 1) / 2
        local sign = if (mod(i, 2) == 1) {
          1
        } else {
          -1
        }
        if (g1 <= k - 1) {
          sum = sum + sign * p[k - g1]
        }
        if (g2 <= k - 1) {
          sum = sum + sign * p[k - g2]
        }
        if (g1 > k - 1 && g2 > k - 1) {
          cont = false
        }
        i = i + 1
      }
      p[k] = sum
    }
    p[n + 1]
  }

