func knapsack01(weights, values, capacity) =
  {
    local n = weights.listLen()
    local dp = []
    for (i: 0 .. n step 1) {
      local row = []
      for (j: 0 .. capacity step 1) {
        row.add(0)
      }
      dp.add(row)
    }
    for (i: 2 .. n + 1 step 1) {
      for (j: 1 .. capacity + 1 step 1) {
        local w = weights[i - 1]
        local v = values[i - 1]
        local jidx = j
        dp[i][jidx] = dp[i - 1][jidx]
        if (w <= jidx - 1 && dp[i - 1][jidx - w] + v > dp[i][jidx]) {
          dp[i][jidx] = dp[i - 1][jidx - w] + v
        }
      }
    }
    dp[n + 1][capacity + 1]
  }

