func aStarPath(grid, size, startR, startC, goalR, goalC) =
  {
    local open = [[0 + abs(goalR - startR) + abs(goalC - startC), 0, startR, startC, []]]
    local visited = {  }
    local result = []
    local found = false
    while (open.listLen() > 0 && (!found)) {
      open = open.sort()
      local cur = open[1]
      open.remove(1)
      local f = cur[1]
      local g = cur[2]
      local r = cur[3]
      local c = cur[4]
      local path = cur[5]
      local key = r _ "," _ c
      if (!visited.containsKey(key)) {
        visited.set(key, true)
        local newPath = copyList(path)
        newPath.add([r, c])
        if (r == goalR && c == goalC) {
          result = newPath
          found = true
        } else {
          local dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]]
          for (d in dirs) {
            local nr = r + d[1]
            local nc = c + d[2]
            local nk = nr _ "," _ nc
            if (nr >= 1 && nr <= size && nc >= 1 && nc <= size && grid[nr][nc] == 0 && (!visited.containsKey(nk))) {
              local ng = g + 1
              local nh = abs(goalR - nr) + abs(goalC - nc)
              open.add([ng + nh, ng, nr, nc, newPath])
            }
          }
        }
      }
    }
    result
  }

