        local s = 0
        for (k: 1 .. p step 1) {
          s = s + A[i][k] * B[k][j]
        }
        row.add(s)
      }
      C.add(row)
    }
    C
  }

func matPow(A, n) =
  {
    local result = [[1, 0], [0, 1]]
    local base = A
    local exp_n = n
    while (exp_n > 0) {
      if (exp_n % 2 == 1) {
        result = matMul(result, base)
      }
      base = matMul(base, base)
      exp_n = floor(exp_n / 2)
    }
    result
  }

