func particle_swarm(f_name, bounds, n_particles, iters) =
  {
    local lo = bounds[1]
    local hi = bounds[2]
    local pos = []
    local vel = []
    local pbest = []
    local pbest_val = []
    for (i: 1 .. n_particles step 1) {
