      pos.add(p)
      vel.add(randFloat() - 0.5)
      pbest.add(p)
      pbest_val.add(p ^ 2)
    }
    local gbest = pos[1]
    local gbest_val = pos[1] ^ 2
    for (i: 1 .. n_particles step 1) {
      if (pbest_val[i] < gbest_val) {
        gbest = pbest[i]
        gbest_val = pbest_val[i]
      }
    }
    for (iter_p: 1 .. iters step 1) {
      for (i: 1 .. n_particles step 1) {
        vel[i] = 0.7 * vel[i] + 1.5 * randFloat() * (pbest[i] - pos[i]) + 1.5 * randFloat() * (gbest - pos[i])
        pos[i] = pos[i] + vel[i]
        local val = pos[i] ^ 2
        if (val < pbest_val[i]) {
          pbest[i] = pos[i]
          pbest_val[i] = val
          if (val < gbest_val) {
            gbest = pos[i]
            gbest_val = val
          }
        }
      }
