func fourier_series_coeffs(f_name, n, period) =
  {
    local T = period
    local coeffs = []
    local N_quad = 1000
    local dt = T / N_quad
    for (k: 0 .. n step 1) {
      local a_k = 0
      local b_k = 0
      for (j: 0 .. N_quad - 1 step 1) {
        local t = j * dt
        local ft = if (t < T / 2) {
          1
        } else {
          -1
        }
        a_k = a_k + ft * cos(2 * 3.14159265 * k * t / T) * dt
        b_k = b_k + ft * sin(2 * 3.14159265 * k * t / T) * dt
      }
      coeffs.add({ "k" : k, "a" : 2 * a_k / T, "b" : 2 * b_k / T })
    }
    coeffs
  }

