func kaplan_meier(times, events) =
  {
    local n = times.listLen()
    local sorted_t = copyList(times)
    sorted_t = sorted_t.sort()
    local unique_t = []
    for (t in sorted_t) {
      if (unique_t.listLen() == 0 || unique_t[unique_t.listLen()] != t) {
        unique_t.add(t)
      }
    }
    local S = 1.0
    local curve_t = []
    local curve_s = []
    local n_at_risk = n
    for (tj in unique_t) {
      local d_j = 0
      local c_j = 0
      for (i: 1 .. n step 1) {
        if (times[i] == tj) {
          if (events[i] == 1) {
            d_j = d_j + 1
          } else {
            c_j = c_j + 1
          }
        }
      }
      S = S * (1 - d_j / n_at_risk)
      n_at_risk = n_at_risk - d_j - c_j
      curve_t.add(tj)
      curve_s.add(S)
    }
    { "t" : curve_t, "S" : curve_s }
  }

