func finiteDifference(u0, bc, dt, dx, steps, scheme) =
  {
    local u = copyList(u0)
    local n = u.listLen()
    for (stepVar: 1 .. steps step 1) {
      local u_new = copyList(u)
      for (i: 2 .. n - 1 step 1) {
        if (scheme === "explicit") {
          u_new[i] = u[i] + (dt / dx) ^ 2 * (u[i + 1] - 2 * u[i] + u[i - 1])
        } else {
          u_new[i] = u[i] + (dt / dx) ^ 2 * (u[i + 1] - 2 * u[i] + u[i - 1])
        }
      }
      u_new[1] = bc.get("left", [])
      u_new[n] = bc.get("right", [])
      u = u_new
    }
    u
  }

