func deinterleave_bits(z) =
  {
    local x = 0
    local y = 0
    local bit = 0
    local zz = z
    while (zz > 0) {
      x = x + (zz % 2 * 2) ^ bit
      zz = floor(zz / 2)
      y = y + (zz % 2 * 2) ^ bit
      zz = floor(zz / 2)
      bit = bit + 1
    }
    { "x" : x, "y" : y }
  }

func interleave_bits(x, y) =
  {
    local z = 0
    local xx = x
    local yy = y
    local bit = 0
    while (xx > 0 || yy > 0) {
      z = z + (xx % 2 * 2) ^ (2 * bit)
      z = z + (yy % 2 * 2) ^ (2 * bit + 1)
      xx = floor(xx / 2)
      yy = floor(yy / 2)
      bit = bit + 1
    }
    z
  }

