func giniCoefficient(incomes) =
  {
    local sorted = copyList(incomes)
      .sort { a, b -> a < b }
    local n = sorted.listLen()
    if (n == 0) {
      0
    } else {
      local sumAll = sorted
        .reduce(0) { acc, v -> acc + v }
      local runSum = 0
      local giniSum = 0
      for (i: 1 .. n step 1) {
        runSum = runSum + sorted[i]
        local shareY = runSum / sumAll
        local shareX = i / n
        giniSum = giniSum + shareX - shareY
      }
      giniSum / n * 2
    }
  }
