func prim(graph, start) =
  {
    local visited = [start]
    local edges = []
    local mst = []
    for (key, val in graph) {
      if (key === start) {
        for (neighbor, weight in val) {
          edges.add([weight, start, neighbor])
        }
      }
    }
    edges = edges.sort()
    while (edges.listLen() > 0) {
      local best = edges[1]
      edges.remove(1)
      local w = best[1]
      local u = best[2]
      local v = best[3]
      if (!visited.containsItem(v)) {
        visited.add(v)
        mst.add([u, v, w])
        for (key, val in graph) {
          if (key === v) {
            for (neighbor, weight in val) {
              if (!visited.containsItem(neighbor)) {
                edges.add([weight, v, neighbor])
              }
            }
          }
        }
        edges = edges.sort()
      }
    }
    mst
  }

