func dungeonGame(dungeon) =
  {
    local rows = dungeon.listLen()
    local cols = dungeon[1].listLen()
    local dp = []
    for (i: 1 .. rows step 1) {
      local row = []
      for (j: 1 .. cols step 1) {
        row.add(0)
      }
      dp.add(row)
    }
    dp[rows][cols] = if (dungeon[rows][cols] >= 0) {
      1
    } else {
      1 - dungeon[rows][cols]
    }
    for (j: cols - 1 .. 1 step -1) {
      local need = dp[rows][j + 1] - dungeon[rows][j]
      dp[rows][j] = if (need > 1) {
        need
      } else {
        1
      }
    }
    for (i: rows - 1 .. 1 step -1) {
      local need = dp[i + 1][cols] - dungeon[i][cols]
      dp[i][cols] = if (need > 1) {
        need
      } else {
        1
      }
    }
    for (i: rows - 1 .. 1 step -1) {
      for (j: cols - 1 .. 1 step -1) {
        local fromRight = dp[i][j + 1] - dungeon[i][j]
        local fromDown = dp[i + 1][j] - dungeon[i][j]
        local best = if (fromRight < fromDown) {
          fromRight
        } else {
          fromDown
        }
        dp[i][j] = if (best > 1) {
          best
        } else {
          1
        }
      }
    }
    dp[1][1]
  }

