func normalizePoints(points) =
  {
    local minX = points[1][1]
    local minY = points[1][2]
    local maxX = points[1][1]
    local maxY = points[1][2]
    for (p in points) {
      if (p[1] < minX) {
        minX = p[1]
      }
      if (p[2] < minY) {
        minY = p[2]
      }
      if (p[1] > maxX) {
        maxX = p[1]
      }
      if (p[2] > maxY) {
        maxY = p[2]
      }
    }
    local rx = if (maxX == minX) {
      1
    } else {
      maxX - minX
    }
    local ry = if (maxY == minY) {
      1
    } else {
      maxY - minY
    }
    points
      .map { p -> [(p[1] - minX) / rx, (p[2] - minY) / ry] }
