          for (ep in endpoints) {
            local ax = sj[1][1]
            local ay = sj[1][2]
            local bx = sj[2][1]
            local by = sj[2][2]
            local dx = bx - ax
            local dy = by - ay
            local len2 = dx * dx + dy * dy
            if (len2 > 0) {
              local t = ((ep[1] - ax) * dx + (ep[2] - ay) * dy) / len2
              if (t > 0.001 && t < 0.999) {
                local px = ax + t * dx
                local py = ay + t * dy
                local ex = ep[1] - px
                local ey = ep[2] - py
                if (ex * ex + ey * ey < 0.0001) {
                  result.add({ "point" : ep, "segment" : j, "t" : t })
                }
              }
            }
          }
        }
      }
    }
    result
  }

