func subdivideTriangle(a, b, c, depth) =
  {
    if (depth == 0) {
      [[a, b, c]]
    } else {
      local mab = [(a[1] + b[1]) / 2, (a[2] + b[2]) / 2]
      local mbc = [(b[1] + c[1]) / 2, (b[2] + c[2]) / 2]
      local mac = [(a[1] + c[1]) / 2, (a[2] + c[2]) / 2]
      local result = []
      for (t in subdivideTriangle(a, mab, mac, depth - 1)) {
        result.add(t)
      }
      for (t in subdivideTriangle(mab, b, mbc, depth - 1)) {
        result.add(t)
      }
      for (t in subdivideTriangle(mac, mbc, c, depth - 1)) {
        result.add(t)
      }
      for (t in subdivideTriangle(mab, mbc, mac, depth - 1)) {
        result.add(t)
      }
      result
    }
  }

