func encodeCaesar(s, alphabet, shift) =
  {
    local n = alphabet.textLen()
    local result = ""
    for (i: 1 .. s.textLen() step 1) {
      local ch = s.segment(i, 1)
      local idx = 0
      local found = false
      for (j: 1 .. n step 1) {
        if (alphabet.segment(j, 1) === ch) {
          idx = j
          found = true
        }
      }
      if (found) {
        result = result _ alphabet.segment(idx - 1 + shift % n + 1, 1)
      } else {
        result = result _ ch
      }
    }
    result
  }

