func fftMagnitudes(signal) =
  {
    local n = signal.listLen()
    local mags = []
    for (k: 0 .. n - 1 step 1) {
      local re = 0
      local im = 0
      for (t: 0 .. n - 1 step 1) {
        local angle = 2 * 3.14159265 * k * t / n
        re = re + signal[t + 1] * cos(angle)
        im = im - signal[t + 1] * sin(angle)
      }
