func damerauLevenshtein(a, b) =
  {
    local m = a.textLen()
    local n = b.textLen()
    local dp = []
    for (i: 0 .. m step 1) {
      local row = []
      for (j: 0 .. n step 1) {
        row.add(0)
      }
      dp.add(row)
    }
    for (i: 0 .. m step 1) {
      dp[i + 1][1] = i
    }
    for (j: 0 .. n step 1) {
      dp[1][j + 1] = j
    }
    for (i: 1 .. m step 1) {
      for (j: 1 .. n step 1) {
        local cost = if (a.segment(i, 1) === b.segment(j, 1)) {
          0
        } else {
          1
        }
        dp[i + 1][j + 1] = min(dp[i][j] + cost, min(dp[i + 1][j] + 1, dp[i][j + 1] + 1))
        if (i > 1 && j > 1 && a.segment(i, 1) === b.segment(j - 1, 1) && a.segment(i - 1, 1) === b.segment(j, 1)) {
          dp[i + 1][j + 1] = min(dp[i + 1][j + 1], dp[i - 1][j - 1] + cost)
        }
      }
    }
    dp[m + 1][n + 1]
  }

