func ufInit(n) {
  this.ufParent = []
  this.ufRank = []
  for (i: 1 .. n step 1) {
    this.ufParent.add(i)
    this.ufRank.add(0)
  }
}
func ufFind(x) =
  {
    if (this.ufParent[x] != x) {
      this.ufParent[x] = ufFind(this.ufParent[x])
    }
    this.ufParent[x]
  }

func ufUnion(a, b) =
  {
    local pa = ufFind(a)
    local pb = ufFind(b)
    if (pa == pb) {
      false
    } else {
      if (this.ufRank[pa] < this.ufRank[pb]) {
        this.ufParent[pa] = pb
      } else if (this.ufRank[pa] > this.ufRank[pb]) {
        this.ufParent[pb] = pa
      } else {
        this.ufParent[pb] = pa
        this.ufRank[pa] = this.ufRank[pa] + 1
      }
      true
    }
  }

