global minHeapArr = []
func hpush(v) {
  this.minHeapArr.add(v)
  local i = this.minHeapArr.listLen()
  while (i > 1 && this.minHeapArr[floor(i / 2)] > this.minHeapArr[i]) {
    local parent = floor(i / 2)
    local t = this.minHeapArr[parent]
    this.minHeapArr[parent] = this.minHeapArr[i]
    this.minHeapArr[i] = t
    i = parent
  }
}
func hpop() {
  local top = this.minHeapArr[1]
  local n = this.minHeapArr.listLen()
  this.minHeapArr[1] = this.minHeapArr[n]
  this.minHeapArr.remove(n)
  local i = 1
  local size = this.minHeapArr.listLen()
  local done = false
  while (!done) {
    local smallest = i
    if (2 * i <= size && this.minHeapArr[2 * i] < this.minHeapArr[smallest]) {
      smallest = 2 * i
    }
    if (2 * i + 1 <= size && this.minHeapArr[2 * i + 1] < this.minHeapArr[smallest]) {
      smallest = 2 * i + 1
    }
    if (smallest != i) {
      local t = this.minHeapArr[i]
      this.minHeapArr[i] = this.minHeapArr[smallest]
      this.minHeapArr[smallest] = t
      i = smallest
    } else {
      done = true
    }
  }
}
