func wrapText(s, width) =
  {
    local ws = s.splitAtSpaces()
      .filter { w -> !w ? emptyText }
    local lines = []
    local current = ""
    for (w in ws) {
      if (current ? emptyText) {
        current = w
      } else if ((current _ " " _ w).textLen() <= width) {
        current = current _ " " _ w
      } else {
        lines.add(current)
        current = w
      }
    }
    if (!current ? emptyText) {
      lines.add(current)
    }
    lines.join("\\n")
  }

println(wrapText("The quick brown fox jumps over the lazy dog and then ran away into the forest", 20))
