func regexLite(pattern, s) =
  {
    local pLen = pattern.textLen()
    local sLen = s.textLen()
    local found = false
    for (i: 1 .. sLen - pLen + 1 step 1) {
      local match = true
      for (j: 1 .. pLen step 1) {
        local pc = pattern.segment(j, 1)
        local sc = s.segment(i + j - 1, 1)
        if (pc !== "." && pc !== sc) {
          match = false
        }
      }
      if (match) {
        found = true
      }
    }
    found
  }

