func scanTokens(code) =
  {
    local result = []
    local i = 1
    local syms = ["+", "-", "*", "/", "(", ")", ","]
    while (i <= code.textLen()) {
      local ch = code.segment(i, 1)
      if (ch === " ") {
        i = i + 1
      } else if (ch ? base10) {
        local tok = ""
        while (i <= code.textLen() && (code.segment(i, 1) ? base10)) {
          tok = tok _ code.segment(i, 1)
          i = i + 1
        }
        result.add({ "type" : "INT", "val" : tok })
      } else if (syms.containsItem(ch)) {
        result.add({ "type" : "SYM", "val" : ch })
        i = i + 1
      } else {
        local tok = ""
        while (i <= code.textLen() && (!syms.containsItem(code.segment(i, 1))) && (!code.segment(i, 1) ? base10) && code.segment(i, 1) !== " ") {
          tok = tok _ code.segment(i, 1)
          i = i + 1
        }
        result.add({ "type" : "IDENT", "val" : tok })
      }
    }
    result
  }

