func prettyAST(node, indent) =
  {
    local prefix = ""
    for (i: 1 .. indent * 2 step 1) {
      prefix = prefix _ " "
    }
    local kind = node.get("kind", [])
    if (kind === "num") {
      prefix _ "num(" _ node.get("val", []) _ ")"
    } else if (kind === "var") {
      prefix _ "var(" _ node.get("name", []) _ ")"
    } else if (kind === "binop") {
      local left = prettyAST(node.get("left", []), indent + 1)
      local right = prettyAST(node.get("right", []), indent + 1)
      prefix _ "binop(" _ node.get("op", []) _ ")\\n" _ left _ "\\n" _ right
    } else {
      prefix _ kind
    }
  }

