func constantFold(node) =
  {
    local kind = node.get("kind", [])
    if (kind === "binop") {
      local left = constantFold(node.get("left", []))
      local right = constantFold(node.get("right", []))
      if (left.get("kind", []) === "num" && right.get("kind", []) === "num") {
        local l = left.get("val", [])
        local r = right.get("val", [])
        local op = node.get("op", [])
        local result = if (op === "+") {
          l + r
        } else if (op === "-") {
          l - r
        } else if (op === "*") {
          l * r
        } else {
          l / r
        }
        { "kind" : "num", "val" : result }
      } else {
        { "kind" : "binop", "op" : node.get("op", []), "left" : left, "right" : right }
      }
    } else {
      node
    }
  }

