func huffmanFreq(s) =
  {
    local freq = {  }
    for (i: 1 .. s.textLen() step 1) {
      local ch = s.segment(i, 1)
      freq.set(ch, if (freq.containsKey(ch)) {
        freq.get(ch, []) + 1
      } else {
        1
      })
    }
    local pq = freq.toPairs()
      .map { p -> [p[2], p[1]] }
      .sort { a, b -> a[1] < b[1] }
    while (pq.listLen() > 1) {
      local left = pq[1]
      pq.remove(1)
      local right = pq[1]
      pq.remove(1)
      local merged = [left[1] + right[1], "(" _ left[2] _ "+" _ right[2] _ ")"]
      local i = 1
      while (i <= pq.listLen() && pq[i][1] < merged[1]) {
        i = i + 1
      }
      pq.insert(i, merged)
      println("Merged: " _ merged[2] _ " freq=" _ merged[1])
    }
    pq[1]
  }

